// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/git/FooterShots.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * The Git pages' tile footer scenes: branch and pull request, failing CI, a
 * shared branch, and landing a worktree. Each is a short card framed at full
 * size on the footers, not the whole window: two stacked tiles of the
 * window's left column (the upper one's last terminal lines and footer, the
 * lower one whole), and for Land the worktree tile's footer under the merge
 * confirmation.
 *
 * Every card edge falls between two terminal lines or in a gap of the grid.
 * A tile's screen fills from the top in whole 15px rows (6px padding above,
 * 10px below, above the footer), so the grid tracks are set in pixels, each
 * framed tile exactly as tall as its capture: the
 * window's grid area is x 10..1430, y 52..890 with 10px gaps, and a tile is
 * its 1px border, 30px header, body and 22px footer.
 */
import type { ReactNode } from "react";
import { Term } from "../../home/AppUI";
import { AnsiScreen } from "../../home/ansi";
import type { CaptureId } from "../../home/captures";
import { Shot } from "../../home/Chrome";
import { ActiveCanvas } from "../../home/Interactive";
import { AppWindow, WIN_SIZE, type Box } from "../../home/Scenes";
import type { BackdropScene } from "../../home/Backdrop";
import { GitTile } from "./GitTile";
import { Confirmation, windowViewport } from "./Modal";
import type { TileFooterInfo } from "./TileFooter";

interface FooterTile {
  title: string;
  capture: CaptureId;
  footer: TileFooterInfo;
}

const GRID_TOP = 52;
const GRID_BOTTOM = 890;
const GAP = 10;
/** A tile's border, header and footer around its body; the body's screen loses 16px of padding. */
const TILE_CHROME = 1 + 30 + 22 + 1;
const SCREEN_PAD = 16;
const LINE = 15;

/** A tile height whose screen shows exactly `lines` terminal lines. */
const tileFor = (lines: number) => lines * LINE + SCREEN_PAD + TILE_CHROME;
/** Where a tile ending at `bottom` has the top of its `n`th line from the bottom (+1px, inside its leading). */
const lineTop = (bottom: number, n: number) => bottom - 1 - 22 - 10 - n * LINE + 1;

function FooterGrid({ tiles, active, grid, box, backdrop, card, overlay }: {
  tiles: FooterTile[];
  active: number;
  grid: { gridTemplateColumns: string; gridTemplateRows: string };
  box: Box;
  backdrop: BackdropScene;
  card: { width: number; height: number };
  overlay?: ReactNode;
}) {
  return (
    <Shot id={backdrop} width={card.width} height={card.height}>
      <div style={{ display: "contents", ...windowViewport(WIN_SIZE.width, WIN_SIZE.height) }}>
        <AppWindow box={box}>
          <ActiveCanvas
            initial={active}
            style={grid}
            tiles={tiles.map((tile, index) => (
              <GitTile key={tile.title} title={tile.title} kbd={`⌘${index + 1}`} footer={tile.footer}>
                <Term>
                  <AnsiScreen id={tile.capture} />
                </Term>
              </GitTile>
            ))}
          />
          {overlay}
        </AppWindow>
      </div>
    </Shot>
  );
}

/* ----------------------------------------------- the stacked footer card -- */

// Three rows (the app's rows resize; see TileResizeHandles): tiles above the
// card, then a tile exactly as tall as its 24-row capture, so its last rows
// (the prompt and status line) sit right above its footer, then a short one
// of six rows. Tiles are listed row by row; the framed ones are the left
// column's 3rd and 5th. The card starts three rows above the middle tile's
// footer and ends 16px below the window, the width of the column.
const MIDDLE = tileFor(24);
const LOWER = tileFor(6);
const UPPER = GRID_BOTTOM - GRID_TOP - 2 * GAP - MIDDLE - LOWER;
const STACK_GRID = { gridTemplateColumns: "705px 705px", gridTemplateRows: `${UPPER}px ${MIDDLE}px ${LOWER}px` };
const STACK_TOP = lineTop(GRID_TOP + UPPER + GAP + MIDDLE, 3);
const STACK = { width: 740, height: WIN_SIZE.height + 16 - STACK_TOP };
const STACK_BOX: Box = { left: 16, top: -STACK_TOP, ...WIN_SIZE };

function StackShot({ tiles, backdrop }: { tiles: FooterTile[]; backdrop: BackdropScene }) {
  return <FooterGrid tiles={tiles} active={4} grid={STACK_GRID} box={STACK_BOX} backdrop={backdrop} card={STACK} />;
}

