const WEB: FooterTile = { title: "web", capture: "web-86", footer: { session: "web", git: { branch: "feat/note-search", ahead: 0, behind: 0 }, pr: { number: 42, state: "OPEN", checks: "pending" }, web: true, agent: true, path: "~/fieldnotes/web", started: "00:58" } };
const RELEASE: FooterTile = { title: "release", capture: "release-86", footer: { session: "release", git: { branch: "release/1.4", ahead: 0, behind: 0 }, pr: { number: 39, state: "MERGED", checks: "passing" }, web: true, agent: true, worktree: { base: "main" }, path: "~/fieldnotes/api.worktrees/release", started: "00:58" } };
const EXPORT: FooterTile = { title: "export", capture: "release-86", footer: { session: "export", git: { branch: "pzza/export", ahead: null, behind: null }, web: true, agent: true, worktree: { base: "main" }, path: "~/fieldnotes/web.worktrees/export", started: "01:02" } };
const GUIDE: FooterTile = { title: "guide", capture: "web-86", footer: { session: "guide", git: { branch: "pzza/guide", ahead: null, behind: null }, web: true, agent: true, worktree: { base: "main" }, path: "~/fieldnotes/docs.worktrees/guide", started: "01:14" } };

