/* ----------------------------------------------------------------- land -- */

// The worktree session's Merge was pressed: its footer button spins while the
// app's confirmation waits (src/worktreeLand.ts, mergeWorktree). The worktree
// tile is the middle one of a 3 x 2 grid, its footer just under the dialog;
// the card is that column, its sides in the column gaps, from 25 lines above
// the footer down to the gap under it.
const LAND_BRANCH = "pzza/search";
const plainTile = (title: string, capture: CaptureId, path: string, started: string, branch = "main"): FooterTile => ({
  title,
  capture,
  footer: { session: title, git: { branch, ahead: 0, behind: 0 }, web: true, agent: true, path, started },
});
const LAND_TILES: FooterTile[] = [
  plainTile("api", "api-57", "~/fieldnotes/api", "00:58"),
  {
    title: "search",
    // A 60-row capture of an agent editing code: the screen shows its newest 33 rows, full to the footer.
    capture: "att-1",
    footer: {
      session: "search",
      git: { branch: LAND_BRANCH, ahead: null, behind: null },
      web: true,
      agent: true,
      worktree: { base: "main", busy: "merge" },
      path: "~/fieldnotes/web.worktrees/search",
    },
  },
  plainTile("docs", "docs-57", "~/fieldnotes/docs", "01:09"),
  plainTile("web", "release-57", "~/fieldnotes/web", "00:58"),
  plainTile("export", "api-57", "~/fieldnotes/api.worktrees/export", "01:02", "pzza/export"),
  plainTile("guide", "docs-57", "~/fieldnotes/docs.worktrees/guide", "01:14", "pzza/guide"),
];
const LAND_UPPER = 565;
// The middle column is 720px wide, at least the docs column, so the card is
// exactly that column: a narrower card would be widened by the page and show
// the neighbouring tiles cut. Its sides sit in the column gaps (x 350..360 and
// 1080..1090), and the dialog, centred on the window, is centred in it.
const LAND_SIDE = 340;
// The grid area (the window less 10px of canvas padding each side), less the side columns and their gaps.
const LAND_MIDDLE = WIN_SIZE.width - 2 * GAP - 2 * (LAND_SIDE + GAP);
const LAND_GRID = { gridTemplateColumns: `${LAND_SIDE}px ${LAND_MIDDLE}px ${LAND_SIDE}px`, gridTemplateRows: `${LAND_UPPER}px ${GRID_BOTTOM - GRID_TOP - GAP - LAND_UPPER}px` };
const LAND_TOP = lineTop(GRID_TOP + LAND_UPPER, 25);
const LAND_LEFT = GAP + LAND_SIDE + GAP / 2;
const LAND = { width: LAND_MIDDLE + GAP, height: GRID_TOP + LAND_UPPER + 5 - LAND_TOP };
const LAND_BOX: Box = { left: -LAND_LEFT, top: -LAND_TOP, ...WIN_SIZE };

export function LandShot() {
  return (
    <FooterGrid
      tiles={LAND_TILES}
      active={1}
      grid={LAND_GRID}
      box={LAND_BOX}
      backdrop="tasks"
      card={LAND}
      overlay={
        <Confirmation
          title={`Merge ${LAND_BRANCH} into main?`}
          message={`Runs git merge --no-ff ${LAND_BRANCH} in the main checkout of this repository, which must be on main with no uncommitted changes. On a conflict the merge is aborted and main stays as it was. Nothing is pushed.`}
          confirmLabel="Merge into main"
        />
      }
    />
  );
}
